        q = deque([start])
        while q:
            u = q.popleft()
            if depth[u] >= (max_len + 1) // 2:
                continue
            for v in adj[u]:
                if v not in depth:
                    depth[v] = depth[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent.get(u, -1) and parent.get(v, -1) != u:
                    cycle_len = depth[u] + depth[v] + 1
                    if cycle_len <= max_len:
                        return True
    return False

def is_3_colorable_fast(adj):
    """Check if graph is 3-colorable using DSATUR-like greedy + backtracking"""
    # Order vertices by degree (descending)
    order = sorted(range(n), key=lambda v: len(adj[v]), reverse=True)
    colors = {}

    def dfs(idx):
        if idx == n:
            return True
        v = order[idx]
        used = set()
        for u in adj[v]:
            if u in colors:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(idx + 1):
                    return True
                del colors[v]
        return False

    return dfs(0)

