                    queue.append(v)
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= 6:
                        # Reconstruct cycle: path from u up to common ancestor, then down to v
                        path_u = [u]
                        cur = u
                        while cur != start:
                            cur = parent[cur]
                            path_u.append(cur)
                        path_v = [v]
                        cur = v
                        while cur != start:
                            cur = parent[cur]
                            path_v.append(cur)
                        # Find common ancestor
                        # Actually, the cycle is: u -> ... -> common -> ... -> v -> u
                        # Let's find the first common vertex in path_u and path_v
                        # Since BFS from start, the common ancestor is the first vertex where paths meet
                        # But we need to find where they diverge
                        # Simpler: use thedist-based approach
                        a, b = u, v
                        while a != b:
                            if dist[a] >= dist[b]:
                                a = parent[a]
                            else:
                                b = parent[b]
                        # Now a == b is the common ancestor
                        common = a
                        # Build path from u to common
                        path_u = [u]
                        while path_u[-1] != common:
                            path_u.append(parent[path_u[-1]])
                        # Build path from v to common
                        path_v = [v]
                        while path_v[-1] != common:
                            path_v.append(parent[path_v[-1]])
                        # Cycle: u -> ... -> common -> ... -> v -> u
                        cycle = path_u + path_v[::-1]
                        return cycle
    return None

