    shortest = float('inf')
    shortest_cycle = None
    for start in range(n):
        parent = {start: -1}
        dist = {start: 0}
        q = deque([start])
        while q:
            v = q.popleft()
            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    q.append(u)
                elif u != parent.get(v, -1):
