                    continue
                a, b = min(i, k), max(i, k)
                c, d = min(k, j), max(k, j)
                e, f = min(j, l), max(j, l)
                g, h = min(l, i), max(l, i)
                s.add(z3.Not(z3.And(edges[(a,b)], edges[(c,d)], edges[(e,f)], edges[(g,h)])))

