def find_short_cycle(edges_set, max_len=6):
    """Find a cycle of length <= max_len in the graph represented by edges_set"""
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for (u, v) in edges_set:
        adj[u].add(v)
        adj[v].add(u)

    # Use BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find cycle
        parent = {start: -1}
        depth = {start: 0}
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in depth:
                    depth[v] = depth[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent.get(u, -1):
                    # Found a cycle
                    # Reconstruct
                    cycle_len = depth[u] + depth[v] + 1
                    if cycle_len <= max_len:
                        # Reconstruct cycle
                        cycle = [u]
                        cur = u
                        while cur != start:
                            cur = parent[cur]
                            if cur == -1:
